#include <stdio.h>
#include <string.h>

#define MOD 1000000007

int a[20][20];
long long dp[1 << 20];

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf("%d", &a[i][j]);

    dp[0] = 1;
    for (int mask = 1; mask < (1 << n); mask++) {
        dp[mask] = 0;
        // count bits set in mask = which man we're assigning
        int bits = __builtin_popcount(mask);
        int man = bits - 1; // 0-indexed man
        // try each woman in mask
        for (int j = 0; j < n; j++) {
            if (mask & (1 << j)) {
                if (a[man][j]) {
                    dp[mask] = (dp[mask] + dp[mask ^ (1 << j)]) % MOD;
                }
            }
        }
    }

    printf("%lld\n", dp[(1 << n) - 1]);
    return 0;
}

