#define MOD 1000000007LL

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    static int a[21][21];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%d", &a[i][j]);
        }
    }

    int total = 1 << N;
    static long long dp[1 << 21];
    memset(dp, 0, sizeof(dp));
    dp[0] = 1;

    for (int mask = 0; mask < total; mask++) {
        int man = 0;
        int x = mask;
        while (x) {
            man += x & 1;
            x >>= 1;
        }

        if (man >= N) continue;

        for (int w = 0; w < N; w++) {
            if (((mask >> w) & 1) == 0 && a[man][w] == 1) {
                int nmask = mask | (1 << w);
                dp[nmask] += dp[mask];
                if (dp[nmask] >= MOD) dp[nmask] -= MOD;
            }
        }
    }

    printf("%lld\n", dp[total - 1] % MOD);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<vector<int>> a(n, vector<int>(n));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> a[i][j];

    // Ryser's formula for permanent
    // perm(A) = (-1)^n * sum_{S subset of [n]} (-1)^|S| * prod_{i=1}^{n} sum_{j in S} a[i][j]

    long long result = 0;

    for (int mask = 0; mask < (1 << n); mask++) {
        int bits = __builtin_popcount(mask);

        // compute product over rows of (sum of a[i][j] for j in mask)
        long long prod = 1;
        for (int i = 0; i < n; i++) {
            long long row_sum = 0;
            for (int j = 0; j < n; j++) {
                if (mask & (1 << j)) {
                    row_sum += a[i][j];
                }
            }
            prod = (prod * row_sum) % MOD;
        }

        // (-1)^|S|
        if ((n - bits) % 2 == 0) {
            // (-1)^n * (-1)^|S| = (-1)^(n-bits)
            // if n-bits is even, add
            result = (result + prod) % MOD;
        } else {
            result = (result - prod + MOD) % MOD;
        }
    }

    cout << result << endl;

    return 0;
}

