static const int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> a(N, vector<int>(N));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> a[i][j];
        }
    }

    // dp[mask] = number of ways to match the first popcount(mask) men
    // using exactly the women included in mask.
    vector<int> dp(1 << N, 0);
    dp[0] = 1;

    for (int mask = 0; mask < (1 << N); ++mask) {
        int man = __builtin_popcount((unsigned)mask);
        if (man >= N) continue;

        for (int woman = 0; woman < N; ++woman) {
            if (!(mask & (1 << woman)) && a[man][woman]) {
                int nextMask = mask | (1 << woman);
                dp[nextMask] += dp[mask];
                if (dp[nextMask] >= MOD) dp[nextMask] -= MOD;
            }
        }
    }

    cout << dp[(1 << N) - 1] << '\n';
    return 0;
}

