public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[][] a = new int[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                a[i][j] = fs.nextInt();
            }
        }

        int size = 1 << N;
        long[] dp = new long[size];
        dp[0] = 1;

        for (int mask = 0; mask < size; mask++) {
            int man = Integer.bitCount(mask);
            if (man >= N) continue;

            long cur = dp[mask];
            if (cur == 0) continue;

            for (int woman = 0; woman < N; woman++) {
                if (((mask >> woman) & 1) == 0 && a[man][woman] == 1) {
                    int nextMask = mask | (1 << woman);
                    dp[nextMask] += cur;
                    if (dp[nextMask] >= MOD) dp[nextMask] -= MOD;
                }
            }
        }

        System.out.println(dp[size - 1] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

